+		app.Use(func(c Ctx) error { called = true; return c.Next() })
+		app.Get("/ok", func(c Ctx) error { return c.SendString("ok") })
+
+		resp, err := app.Test(httptest.NewRequest(MethodGet, "/nope", http.NoBody))
