+	c = app.AcquireCtx(&fasthttp.RequestCtx{})
+	err = c.Format(handler("default"))
+	require.NoError(t, err)
+	require.Equal(t, "default", accepted)
+	require.NotEqual(t, "default", c.GetRespHeader(HeaderContentType))
+}
