+		"Wednesday, 21-Oct-15 07:28:00 GMT", // obsolete RFC 850 format
+		"Wed Oct 21 07:28:00 2015",          // ANSI C asctime() format
+	} {
+		c := app.AcquireCtx(&fasthttp.RequestCtx{})
+		c.Request().Header.Set(HeaderIfModifiedSince, date)
