+	c.Request().Header.Set(HeaderIfModifiedSince, "Wednesday, 21-Oct-15 07:28:00 GMT")
+	c.Response().Header.Set(HeaderLastModified, "Wed, 21 Oct 2015 07:29:00 GMT")
+	require.False(t, c.Fresh())
+}
