+	require.False(t, containsInvalidHeaderChars("Basic\tQWxhZGRpbjpvcGVuIHNlc2FtZQ=="))
+	require.False(t, containsInvalidHeaderChars("Basic Q"))
+	require.False(t, containsInvalidHeaderChars(" ~\t"))
+
