+// go test -run Test_MemoryLock_NoKeyLeak
+func Test_MemoryLock_NoKeyLeak(t *testing.T) {
+	t.Parallel()
+
+	const keys = 1000
+
+	l := NewMemoryLock()
+
+	for i := 0; i < keys; i++ {
+		key := strconv.Itoa(i)
+		utils.AssertEqual(t, nil, l.Lock(key))
+		utils.AssertEqual(t, nil, l.Unlock(key))
